import{_ as e,c as a,o as r,a4 as t}from"./chunks/framework.DzOtv0XR.js";const v=JSON.parse('{"title":"vite","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/vite.md","filePath":"frameworks/vite.md"}'),l={name:"frameworks/vite.md"},o=t('<h1 id="vite" tabindex="-1">vite <a class="header-anchor" href="#vite" aria-label="Permalink to &quot;vite&quot;">​</a></h1><p>ES6 module + rollup-based for production</p><p>浏览器原生支持，实现无刷更新。</p><p>静态资源处理，借助 npm &amp; CDN</p><p>旧页面 301 重定向到新页面</p><h2 id="与-webpack-比较" tabindex="-1">与 webpack 比较 <a class="header-anchor" href="#与-webpack-比较" aria-label="Permalink to &quot;与 webpack 比较&quot;">​</a></h2><p>定位不同，vite 是上层工具链，依赖 rollup，而 webpack 与 rollup 对标</p><h2 id="es-module-based-dev-server-vs-bundle-based-dev-server" tabindex="-1">ES module based dev server VS Bundle based dev server <a class="header-anchor" href="#es-module-based-dev-server-vs-bundle-based-dev-server" aria-label="Permalink to &quot;ES module based dev server VS Bundle based dev server&quot;">​</a></h2><ul><li>全量打包，项目越大，打包越慢 <ul><li>解析每个文件的导入导出关系</li><li>排序、重写，连接模块</li></ul></li><li>代码分割是针对生产环境</li></ul><p>[[vite多久后能干掉webpack？ - 知乎]]</p><h2 id="问题-模块多-http-请求多" tabindex="-1">问题，模块多，HTTP 请求多 <a class="header-anchor" href="#问题-模块多-http-请求多" aria-label="Permalink to &quot;问题，模块多，HTTP 请求多&quot;">​</a></h2><ol><li>预打包依赖，一个依赖一个请求</li><li>etag &amp; 304</li><li>代码分割，ES module 同时支持 dev &amp; prod</li></ol><h2 id="依赖预构建" tabindex="-1">依赖预构建 <a class="header-anchor" href="#依赖预构建" aria-label="Permalink to &quot;依赖预构建&quot;">​</a></h2><p>原因</p><ol><li>兼容性，cjs/umd 转为 esm</li><li>性能，减少请求数</li></ol><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><p><a href="https://docs.google.com/presentation/d/1X1hrFw18v67bEniTPpaI_DBulLdkKNFEc_3nVEm95mM/edit#slide=id.p" target="_blank" rel="noreferrer">Vite &amp; VitePress @ Vue Toronto 2020 - Google 幻灯片</a></p><p><a href="https://chengpeiquan.com/article/rewrite-in-vite.html" target="_blank" rel="noreferrer">博客重构于Vite - 程沛权 - 养了三只猫</a></p><blockquote><p>vite在dev下有明显的性能提升，体验是飞速的，但是在浏览器请求页面时，会同时加载大量js文件，这导致在速度上也有一定的牺牲，而webpack在构建上确实会慢很多，并且项目的文件越多越慢，但是一但构建好，在浏览器端体验是要比vite快的。另外vite即便是在生产环境下采用rollup对文件进行打包，但是对于IE的支持还是不好，并且生产打包的速度和webpack基本上一致，总之，如果项目已经很稳定并且很庞大，不建议换vite。</p></blockquote><p><a href="https://www.nihaoshijie.com.cn/index.php/archives/1903/" target="_blank" rel="noreferrer">B端系统改造Vite最佳实践 | 吕小鸣前端博客</a></p><h2 id="rolldown" tabindex="-1">Rolldown <a class="header-anchor" href="#rolldown" aria-label="Permalink to &quot;Rolldown&quot;">​</a></h2><p><a href="https://www.cnblogs.com/cuggz/archive/2023/10/06/17744353.html" target="_blank" rel="noreferrer">尤雨溪：Vite的现状与未来展望 - 前端充电宝 - 博客园</a></p>',22),i=[o];function d(s,n,p,h,c,u){return r(),a("div",null,i)}const m=e(l,[["render",d]]);export{v as __pageData,m as default};
